import { expect, expectStatus, test, type Document, type Extraction, type Vendor } from "../../fixtures";

// One vendor's card in the review queue, as the API returns it.
type ReviewQueueItem = {
  vendor_id: string;
  extractions: { kind: string; status: string }[];
};

test("after a replacement, only the new document waits for review", { tag: "@LIF-05" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review, then insurance and contract approved and the w9 rejected
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview({ as: "member" });

  const insurance = await expectStatus<Extraction>(
    await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, { data: { decision: "approve" } }),
    200,
  );
  expect(insurance.status).toBe("approved");
  const contract = await expectStatus<Extraction>(
    await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, { data: { decision: "approve" } }),
    200,
  );
  expect(contract.status).toBe("approved");
  const w9 = await expectStatus<Extraction>(
    await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "reject", note: "W-9 is unsigned" },
    }),
    200,
  );
  expect(w9.status).toBe("rejected");

  // Act: upload a new w9, wait for its extraction, and submit the vendor again
  const replacement = await factory.upload(vendor.id, "w9", "w9.txt", "member");
  await expect
    .poll(
      async () => {
        const documents = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
        return documents.find((d) => d.id === replacement.id)?.status;
      },
      { message: "replacement w9 finishes extraction", timeout: 30_000 },
    )
    .toBe("extracted");
  const submitted = await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

  // Assert: the vendor is in review, and the queue holds only the new w9
  expect(submitted.status).toBe("in_review");
  const stored = await expectStatus<Vendor>(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("in_review");

  const queue = await expectStatus<ReviewQueueItem[]>(await reviewer.get("/api/review-queue"), 200);
  const card = queue.find((item) => item.vendor_id === vendor.id);
  expect(card, "vendor is listed in the review queue").toBeDefined();
  expect(card?.extractions.map((e) => ({ kind: e.kind, status: e.status }))).toEqual([
    { kind: "w9", status: "pending_review" },
  ]);
});
